import {
  Controller,
  Get,
  Post,
  Body,
  Patch,
  Param,
  Delete,
  UseGuards,
  Request,
  UseInterceptors,
  UploadedFile,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { InventoryService } from './inventory.service';
import { JwtAuthGuard } from '../auth/jwt-auth.guard';
import { FileInterceptor } from '@nestjs/platform-express';

@Controller('inventory')
@UseGuards(AuthGuard('jwt'))
export class InventoryController {
  constructor(private readonly inventoryService: InventoryService) {}

  @Get('suppliers')
  async findAllSuppliers() {
    return this.inventoryService.findAllSuppliers();
  }

  @Get('installments/upcoming')
  async getUpcomingInstallments() {
    return this.inventoryService.getUpcomingInstallments();
  }

  @Get('installments/all')
  async getAllUnpaidInstallments() {
    return this.inventoryService.getAllUnpaidInstallments();
  }

  @Get('stats')
  async getInventoryStats() {
    return this.inventoryService.getInventoryStats();
  }

  @Post('suppliers')
  async createSupplier(@Body() data: any) {
    return this.inventoryService.createSupplier(data);
  }

  @Delete('suppliers/:id')
  async deleteSupplier(@Param('id') id: string) {
    return this.inventoryService.deleteSupplier(+id);
  }

  @Patch('suppliers/:id')
  async updateSupplier(@Param('id') id: string, @Body() data: any) {
    return this.inventoryService.updateSupplier(+id, data);
  }

  @Post('stock-in')
  async receiveStock(@Body() data: any, @Request() req: any) {
    return this.inventoryService.receiveStock({
      ...data,
      receivedByUserId: req.user.id,
    });
  }

  @Post('stock-in/:id/pay')
  async payInstallment(
    @Param('id') id: string,
    @Body() data: any,
    @Request() req: any,
  ) {
    return this.inventoryService.payInstallment({
      ...data,
      stockInId: +id,
      userId: req.user.id,
    });
  }

  @Get('stock-in')
  async findAllStockIn() {
    return this.inventoryService.findAllStockIn();
  }

  @Get('stock-in/:id/payments')
  async getPurchaseLedger(@Param('id') id: string) {
    return this.inventoryService.getPurchaseLedger(+id);
  }

  @Get('ingredients')
  async getIngredients() {
    return this.inventoryService.getAllIngredients();
  }

  @Get('low-stock')
  async getLowStockItems() {
    return this.inventoryService.getLowStockItems();
  }

  @Get('mandatory-reporting')
  async getMandatoryReportingItems() {
    return this.inventoryService.getMandatoryReportingItems();
  }

  @Post('ingredients')
  async createIngredient(@Body() data: any) {
    return this.inventoryService.createIngredient(data);
  }

  @UseGuards(JwtAuthGuard)
  @Post('waste')
  async declareWaste(@Body() data: any, @Request() req: any) {
    return this.inventoryService.declareWaste({
      ...data,
      recordedByUserId: req.user.id,
    });
  }

  @Get('waste/history')
  async getWasteHistory() {
    // Basic history, could be expanded
    return []; 
  }

  @Patch('ingredients/:id')
  async updateIngredient(@Param('id') id: number, @Body() data: any, @Request() req: any) {
    return this.inventoryService.updateIngredient(id, data, req.user.id);
  }

  @Delete('ingredients/:id')
  async deleteIngredient(@Param('id') id: number) {
    await this.inventoryService.deleteIngredient(id);
    return { success: true };
  }

  @Patch('ingredients/:id/stock')
  async updateStock(
    @Param('id') id: number,
    @Body('quantity') quantity: number,
    @Body('type') type: 'add' | 'subtract',
    @Body('reason') reason: string,
    @Request() req: any,
  ) {
    return this.inventoryService.updateStock(
      id,
      quantity,
      type,
      req.user.username,
      reason,
      undefined,
      req.user.id,
    );
  }

  @Post('menu-item/:id/recipe')
  async setRecipe(
    @Param('id') menuItemId: number,
    @Body('recipes') recipes: any[],
  ) {
    await this.inventoryService.setRecipe(menuItemId, recipes);
    return { success: true };
  }

  @Get('menu-availability')
  async getMenuAvailability() {
    return this.inventoryService.getMenuAvailability();
  }

  @Post('import')
  @UseInterceptors(FileInterceptor('file'))
  async importFromExcel(@UploadedFile() file: any) {
    if (!file) {
      throw new Error('No file uploaded');
    }
    return this.inventoryService.importFromExcel(file.buffer);
  }
}
